            $this->assertSame(AcosMeasureSeriesFreshnessReader::SCHEMA, $payload['schema_version']);
            $this->assertTrue($payload['fresh']);
            $this->assertSame('acos.test.freshness', $payload['series']);
            $this->assertNotNull($payload['last_append_at']);
        } finally {
            @unlink($path);
        }
    }

